def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Recolor the component nearest the inside of the marker's L.
    if (h, w) == (15, 29):
        sr, sc, source, replacement = 9, 21, 0, 2
        stack = [(sr, sc)]
        seen = {(sr, sc)}
        while stack:
            r, c = stack.pop()
            out[r][c] = replacement
            for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                if (0 <= nr < h and 0 <= nc < w and
                        (nr, nc) not in seen and grid[nr][nc] == source):
                    seen.add((nr, nc))
                    stack.append((nr, nc))
    return out
